function morphPoints(type){return Array.from({length:64},(_,i)=>{let a=i/64*Math.PI*2-Math.PI/2;let r=type===0?68+17*Math.cos(6*a):type===1?76:82/(Math.abs(Math.cos(a))+Math.abs(Math.sin(a)));return[100+Math.cos(a)*r,100+Math.sin(a)*r];});}
