  const panel=q('.cmd-panel'),input=q('.cmd-input'),list=q('.cmd-list'),entry=q('.command-entry'),uid='command-'+(++studyUid);list.id=uid;input.setAttribute('aria-controls',uid);let page='root',active=0,matches=[];
  const rootItems=[['切换工作区','进入下一层','spaces'],['搜索资料','显示资料视图','files'],['开始写笔记','仅操作演示','note']];const spaces=[['设计参考库','切换演示空间','space'],['资料阅读室','切换演示空间','space'],['写作台','切换演示空间','space']];
  function highlight(){[...list.children].forEach((el,i)=>el.setAttribute('aria-selected',String(i===active)));const el=list.children[active];if(el?.getAttribute('role')==='option'){input.setAttribute('aria-activedescendant',el.id);el.scrollIntoView({block:'nearest'});}else input.removeAttribute('aria-activedescendant');}
