function newNodes(root){return extraNodes(root);}
function arcSector(cx,cy,r0,r1,a,b){if(b-a<.0001)return '';const p=(r,v)=>[cx+Math.sin(v)*r,cy-Math.cos(v)*r].join(',');const large=b-a>Math.PI?1:0;return `M${p(r1,a)}A${r1},${r1} 0 ${large} 1 ${p(r1,b)}L${p(r0,b)}A${r0},${r0} 0 ${large} 0 ${p(r0,a)}Z`;}
