 L.on(root,'pointerdown',e=>{if(e.pointerType!=='mouse')set(localPoint(e,scene));});
 root.tabIndex=0;root.setAttribute('role','group');root.setAttribute('aria-label','实时跟随演示，方向键可移动参考点');
 L.on(root,'keydown',e=>{if(!['ArrowLeft','ArrowRight','ArrowUp','ArrowDown','Home'].includes(e.key)||e.target!==root)return;e.preventDefault();set(e.key==='Home'?{x:270,y:170}:{x:clamp(target.x+(e.key==='ArrowLeft'?-32:e.key==='ArrowRight'?32:0),0,540),y:clamp(target.y+(e.key==='ArrowUp'?-26:e.key==='ArrowDown'?26:0),0,340)});});
 // Public to the card lifecycle, not a fabricated pointer event.
